enum RunState: Equatable {
    case idle
    case running(startedAt: Int)
    case paused(elapsed: Int)
    mutating func pause(now: Int) {
        switch self {
        case .running(let startedAt):
            self = .paused(elapsed: now - startedAt)
        case .idle, .paused:
            break
        }
    }
}
var state = RunState.running(startedAt: 100)
state.pause(now: 160)
assert(state == .paused(elapsed: 60))
state.pause(now: 200)
assert(state == .paused(elapsed: 60))
var idle = RunState.idle
idle.pause(now: 50)
assert(idle == .idle)

Метод меняет само значение enum, поэтому он mutating и присваивает self новый случай. Повторная пауза не трогает прошедшие 60 секунд. .idle, .paused перечислены явно вместо default: новый случай (например, .finished) заставит решить, что делает пауза. Equatable синтезируется сам, потому что связанные Int сравнимы.

