enum Freshness {
    case fresh(daysLeft: Int)
    case expired(daysAgo: Int)
}
func badge(_ item: Freshness) -> String {
    switch item {
    case .fresh(let days) where days <= 1: return "Съешь сегодня"
    case .fresh(let days): return "Ещё \(days) дн."
    case .expired(0): return "Истёк сегодня"
    case .expired: return "Выбросить"
    }
}
print(badge(.fresh(daysLeft: 1)))
print(badge(.fresh(daysLeft: 5)))
print(badge(.expired(daysAgo: 0)))
print(badge(.expired(daysAgo: 3)))

